import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Header from '../../components/header';
import './style.css';

export default function CriarSala() {
  const navigate = useNavigate();
  const [questionario, setQuestionario] = useState('');

  const handleCriar = () => {
    if (!questionario) {
      alert('Por favor, selecione um questionário');
      return;
    }

    const codigo = String(Math.floor(100000 + Math.random() * 900000));
    console.log('Criando sala:', { questionario, codigo });

    navigate('/sala', { state: { codigo } });
  };

  const handleFechar = () => {
    navigate('/game');
  };

  return (
    <>
      <Header />
      <div className="criar-sala-container">
        <div className="criar-sala-content">
          <h1 className="criar-sala-title">CRIAR SALA</h1>

          <div className="sala-card">
            <button className="close-btn" onClick={handleFechar}>×</button>

            <div className="form-group">
              <div className="custom-select-wrapper">
                <select
                  className="form-select"
                  value={questionario}
                  onChange={(e) => setQuestionario(e.target.value)}
                >
                  <option value="">Selecione o Questionário</option>
                  <option value="matematica">Matemática</option>
                </select>
              </div>
            </div>

            <button className="criar-btn" onClick={handleCriar}>
              CRIAR
            </button>
          </div>
        </div>
      </div>
    </>
  );
}
